cat << 'BOOTSTRAP_EOF' > /tmp/bootstrap.sh
#!/usr/bin/env bash
set -euo pipefail

echo "==> 1. Installing uv and initializing GitHub Spec Kit..."
curl -LsSf https://astral.sh/uv/install.sh | sh
export PATH="$HOME/.local/bin:$PATH"

# Initialize Spec Kit in the existing repo for Gemini CLI (non-interactive)
uvx --from git+https://github.com/github/spec-kit.git specify init --here --ai gemini --script sh --no-input || true

echo "==> 2. Creating Directory Hierarchy..."
mkdir -p .devcontainer \
         .github/workflows \
                  .specify/memory \
                           specs \
                                    policies/checkov \
                                             policies/opa \
                                                      terraform/modules/workload-service \
                                                               terraform/environments/dev \
                                                                        terraform/environments/prod \
                                                                                 observability/slos \
                                                                                          observability/synthetic \
                                                                                                   observability/dashboards \
                                                                                                            observability/generated

                                                                                                            echo "==> 3. Creating Devcontainer (for seamless laptop use later)..."
                                                                                                            cat << 'EOF' > .devcontainer/devcontainer.json
                                                                                                            {
                                                                                                              "name": "Infra SDD Platform",
                                                                                                                "image": "mcr.microsoft.com/devcontainers/base:ubuntu-24.04",
                                                                                                                  "features": {
                                                                                                                      "ghcr.io/devcontainers/features/terraform:1": {
                                                                                                                            "version": "1.9.8",
                                                                                                                                  "tflint": "latest"
                                                                                                                                      },
                                                                                                                                          "ghcr.io/devcontainers/features/python:1": {
                                                                                                                                                "version": "3.12"
                                                                                                                                                    },
                                                                                                                                                        "ghcr.io/devcontainers/features/node:1": {
                                                                                                                                                              "version": "22"
                                                                                                                                                                  },
                                                                                                                                                                      "ghcr.io/devcontainers/features/docker-in-docker:2": {}
                                                                                                                                                                        },
                                                                                                                                                                          "postCreateCommand": "pip install --break-system-packages checkov pre-commit && npm install -g @google/gemini-cli && curl -LsSf https://astral.sh/uv/install.sh | sh",
                                                                                                                                                                            "customizations": {
                                                                                                                                                                                "vscode": {
                                                                                                                                                                                      "extensions": [
                                                                                                                                                                                              "hashicorp.terraform",
                                                                                                                                                                                                      "GitHub.copilot",
                                                                                                                                                                                                              "Google.geminicodeassist"
                                                                                                                                                                                                                    ]
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                          EOF

                                                                                                                                                                                                                          echo "==> 4. Writing the SDD Constitution (.specify/memory/constitution.md)..."
                                                                                                                                                                                                                          cat << 'EOF' > .specify/memory/constitution.md
                                                                                                                                                                                                                          # Infrastructure & Observability Constitution

                                                                                                                                                                                                                          ## 1. Core IaC & Modularity Principles
                                                                                                                                                                                                                          - **Declarative Standard**: All cloud infrastructure MUST be provisioned using Terraform (`>= 1.9`).
                                                                                                                                                                                                                          - **Strict Modularity**: Environment directories (`terraform/environments/*`) MUST only instantiate modules from `terraform/modules/*`. No raw cloud resources directly in environment roots.
                                                                                                                                                                                                                          - **State Security**: Remote state backends MUST enforce encryption at rest and state locking.

                                                                                                                                                                                                                          ## 2. Zero-Trust Security & SAST Mandates
                                                                                                                                                                                                                          - **Least Privilege**: IAM policies and roles MUST NOT contain wildcard actions (`*`) or wildcard resources (`*`).
                                                                                                                                                                                                                          - **Network Isolation**: Ingress from `0.0.0.0/0` is strictly forbidden except on HTTPS (`443`) via an approved load balancer/WAF.
                                                                                                                                                                                                                          - **Encryption Everywhere**: All storage buckets, managed disks, queues, and databases MUST enforce KMS/CMK encryption at rest and TLS 1.3 in transit.
                                                                                                                                                                                                                          - **Gate Compliance**: No task is complete until `terraform validate`, `checkov`, and `conftest` pass with zero MEDIUM, HIGH, or CRITICAL findings. Inline skip comments (`#checkov:skip`) are forbidden unless explicitly justified in `plan.md`.

                                                                                                                                                                                                                          ## 3. Mandatory Observability-by-Spec
                                                                                                                                                                                                                          - **No Unmonitored Services**: Every infrastructure module or workload deployed in `terraform/` MUST have:
                                                                                                                                                                                                                            1. An accompanying Sloth SLO specification in `observability/slos/<service>.slo.yaml`.
                                                                                                                                                                                                                              2. A synthetic endpoint/health check in `observability/synthetic/endpoints.yaml`.
                                                                                                                                                                                                                              - **Mandatory Resource Tags**: Every taggable Terraform resource MUST include:
                                                                                                                                                                                                                                - `Environment` (`dev` | `prod`)
                                                                                                                                                                                                                                  - `Service`
                                                                                                                                                                                                                                    - `ManagedBy` (`Terraform-SDD`)
                                                                                                                                                                                                                                      - `SecurityTier` (`public` | `internal` | `restricted`)
                                                                                                                                                                                                                                      EOF

                                                                                                                                                                                                                                      echo "==> 5. Writing Baseline OPA/Conftest Policy (policies/opa/tags.rego)..."
                                                                                                                                                                                                                                      cat << 'EOF' > policies/opa/tags.rego
                                                                                                                                                                                                                                      package main

                                                                                                                                                                                                                                      import rego.v1

                                                                                                                                                                                                                                      required_tags := {"Environment", "Service", "ManagedBy", "SecurityTier"}

                                                                                                                                                                                                                                      deny contains msg if {
                                                                                                                                                                                                                                          some resource in input.resource_changes
                                                                                                                                                                                                                                              resource.change.actions[_] in ["create", "update"]
                                                                                                                                                                                                                                                  tags := object.get(resource.change.after, "tags", {})
                                                                                                                                                                                                                                                      missing := required_tags - {k | tags[k]}
                                                                                                                                                                                                                                                          count(missing) > 0
                                                                                                                                                                                                                                                              msg := sprintf("Resource '%s' is missing mandatory constitution tags: %v", [resource.address, missing])
                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                              EOF

                                                                                                                                                                                                                                                              echo "==> 6. Writing Baseline Terraform Root Files (so CI passes immediately)..."
                                                                                                                                                                                                                                                              cat << 'EOF' > terraform/environments/prod/versions.tf
                                                                                                                                                                                                                                                              terraform {
                                                                                                                                                                                                                                                                required_version = ">= 1.9.0"
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                EOF

                                                                                                                                                                                                                                                                cat << 'EOF' > terraform/environments/dev/versions.tf
                                                                                                                                                                                                                                                                terraform {
                                                                                                                                                                                                                                                                  required_version = ">= 1.9.0"
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                  EOF

                                                                                                                                                                                                                                                                  echo "==> 7. Writing Baseline Synthetic Check (observability/synthetic/endpoints.yaml)..."
                                                                                                                                                                                                                                                                  cat << 'EOF' > observability/synthetic/endpoints.yaml
                                                                                                                                                                                                                                                                  endpoints:
                                                                                                                                                                                                                                                                    - name: platform-health-baseline
                                                                                                                                                                                                                                                                        group: core
                                                                                                                                                                                                                                                                            url: "https://status.github.com/api/status.json"
                                                                                                                                                                                                                                                                                interval: 5m
                                                                                                                                                                                                                                                                                    conditions:
                                                                                                                                                                                                                                                                                          - "[STATUS] == 200"
                                                                                                                                                                                                                                                                                                - "[RESPONSE_TIME] < 1000"
                                                                                                                                                                                                                                                                                                EOF

                                                                                                                                                                                                                                                                                                echo "==> 8. Writing Baseline Sloth SLO Spec (observability/slos/core-platform.slo.yaml)..."
                                                                                                                                                                                                                                                                                                cat << 'EOF' > observability/slos/core-platform.slo.yaml
                                                                                                                                                                                                                                                                                                version: "prometheus/v1"
                                                                                                                                                                                                                                                                                                service: "core-platform"
                                                                                                                                                                                                                                                                                                labels:
                                                                                                                                                                                                                                                                                                  owner: "platform-engineering"
                                                                                                                                                                                                                                                                                                    tier: "1"
                                                                                                                                                                                                                                                                                                    slos:
                                                                                                                                                                                                                                                                                                      - name: "requests-availability"
                                                                                                                                                                                                                                                                                                          objective: 99.9
                                                                                                                                                                                                                                                                                                              description: "99.9% of platform requests must succeed."
                                                                                                                                                                                                                                                                                                                  sli:
                                                                                                                                                                                                                                                                                                                        events:
                                                                                                                                                                                                                                                                                                                                error_query: sum(rate(http_request_duration_seconds_count{job="core-platform",code=~"(5..|429)"}[{{.window}}]))
                                                                                                                                                                                                                                                                                                                                        total_query: sum(rate(http_request_duration_seconds_count{job="core-platform"}[{{.window}}]))
                                                                                                                                                                                                                                                                                                                                            alerting:
                                                                                                                                                                                                                                                                                                                                                  name: CorePlatformHighErrorRate
                                                                                                                                                                                                                                                                                                                                                        labels:
                                                                                                                                                                                                                                                                                                                                                                category: "availability"
                                                                                                                                                                                                                                                                                                                                                                      page_alert:
                                                                                                                                                                                                                                                                                                                                                                              labels:
                                                                                                                                                                                                                                                                                                                                                                                        severity: "critical"
                                                                                                                                                                                                                                                                                                                                                                                              ticket_alert:
                                                                                                                                                                                                                                                                                                                                                                                                      labels:
                                                                                                                                                                                                                                                                                                                                                                                                                severity: "warning"
                                                                                                                                                                                                                                                                                                                                                                                                                EOF

                                                                                                                                                                                                                                                                                                                                                                                                                echo "==> 9. Writing GitHub Actions Deployment Blocker (.github/workflows/sdd-security-gate.yml)..."
                                                                                                                                                                                                                                                                                                                                                                                                                cat << 'EOF' > .github/workflows/sdd-security-gate.yml
                                                                                                                                                                                                                                                                                                                                                                                                                name: SDD Security & Observability Gate

                                                                                                                                                                                                                                                                                                                                                                                                                on:
                                                                                                                                                                                                                                                                                                                                                                                                                  push:
                                                                                                                                                                                                                                                                                                                                                                                                                      branches: [ main ]
                                                                                                                                                                                                                                                                                                                                                                                                                        pull_request:
                                                                                                                                                                                                                                                                                                                                                                                                                            branches: [ main ]

                                                                                                                                                                                                                                                                                                                                                                                                                            permissions:
                                                                                                                                                                                                                                                                                                                                                                                                                              contents: read

                                                                                                                                                                                                                                                                                                                                                                                                                              jobs:
                                                                                                                                                                                                                                                                                                                                                                                                                                validate-and-block:
                                                                                                                                                                                                                                                                                                                                                                                                                                    name: validate-and-block
                                                                                                                                                                                                                                                                                                                                                                                                                                        runs-on: ubuntu-latest
                                                                                                                                                                                                                                                                                                                                                                                                                                            steps:
                                                                                                                                                                                                                                                                                                                                                                                                                                                  - name: Checkout Repository
                                                                                                                                                                                                                                                                                                                                                                                                                                                          uses: actions/checkout@v4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  with:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fetch-depth: 0

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  - name: 1. Secret Scanning (Gitleaks)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          uses: gitleaks/gitleaks-action@v2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  env:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  - name: 2. SAST for Scripts & Automation (Semgrep)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          uses: returntocorp/semgrep-action@v1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  with:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            config: p/default

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  - name: 3. Setup Terraform
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          uses: hashicorp/setup-terraform@v3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  with:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            terraform_version: "1.9.8"

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  - name: 4. Terraform Format & Validate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          run: |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    terraform fmt -check -recursive terraform/
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for env in dev prod; do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          terraform -chdir=terraform/environments/$env init -backend=false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      terraform -chdir=terraform/environments/$env validate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                done

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      - name: 5. IaC Static Security Analysis (Checkov)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              uses: bridgecrewio/checkov-action@v12
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      with:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                directory: terraform/
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          framework: terraform
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    hard_fail_on: MEDIUM,HIGH,CRITICAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              compact: true

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    - name: 6. Verify & Compile Sloth SLO Specs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            run: |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      docker run --rm -v "${GITHUB_WORKSPACE}/observability:/obs" ghcr.io/slok/sloth:latest generate \
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  -i /obs/slos/ \
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -o /obs/generated/

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    - name: 7. Verify Spec Kit Constitution Exists
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            run: |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      test -f .specify/memory/constitution.md || (echo "Missing SDD Constitution!" && exit 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      EOF

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "==> 10. Writing .gitignore..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cat << 'EOF' > .gitignore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      **/.terraform/*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *.tfstate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *.tfstate.*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      crash.log
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *.tfvars
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *.tfvars.json
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      override.tf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      override.tf.json
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *_override.tf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      *_override.tf.json
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .terraformrc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      terraform.rc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tfplan.binary
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tfplan.json
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .env
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      EOF

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      # Keep empty directories tracked
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      find specs policies terraform observability -type d -empty -exec touch {}/.gitkeep \;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "==> 11. Committing and Pushing to GitHub..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      git add .
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      git commit -m "feat: initialize SDD platform, constitution, devcontainer, and CI security gates"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      git push origin main

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "✅ BOOTSTRAP COMPLETE! Check the Actions tab in your GitHub repo."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      BOOTSTRAP_EOF
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      bash /tmp/bootstrap.sh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      